W += c[20]*3.0070000000000000e+01; // C2H6
W += c[21]*1.3018999999999998e+01; // CH
W += c[22]*2.6037999999999997e+01; // C2H2
W += c[23]*6.1060000000000002e+01; // C2H4OOH
W += c[24]*2.7045999999999999e+01; // C2H3
W += c[25]*4.3045000000000002e+01; // CH2CHO
W += c[26]*4.1028999999999996e+01; // HCCO
W += c[27]*4.2036999999999999e+01; // CH2CO
W += c[28]*2.5029999999999998e+01; // C2H
W += c[29]*1.3018999999999998e+01; // CHs
W += c[30]*1.7007000000000001e+01; // OHs
W += c[31]*1.9022451420091127e+01; // H3Op
W += c[32]*2.9017451420091128e+01; // HCOp
W += c[33]*4.3044451420091129e+01; // C2H3Op
W += c[34]*3.3049451420091124e+01; // CH5Op
