W += c[8]*3.4014000000000003e+01; // H2O2
W += c[9]*2.8009999999999998e+01; // CO
W += c[10]*4.4009000000000000e+01; // CO2
W += c[11]*2.9018000000000001e+01; // HCO
W += c[12]*1.5035000000000000e+01; // CH3
W += c[13]*1.6042999999999999e+01; // CH4
W += c[14]*3.0026000000000000e+01; // CH2O
W += c[15]*1.4026999999999999e+01; // T-CH2
