CW += c[43]*1.4026999999999999e+01; // CH2
CW += c[44]*3.2042000000000002e+01; // CH3OH
// Now compute conversion
amrex::Real CWinv = 1.0/CW;
y[0] = c[0]*2.8013999999999999e+01*CWinv; 
y[1] = c[1]*1.0080000000000000e+00*CWinv; 
y[2] = c[2]*3.1998000000000001e+01*CWinv; 
y[3] = c[3]*1.7007000000000001e+01*CWinv; 
