k_f = 1300000
           * exp((-1) * logT);
Corr  = mixture + (1.5)*sc[5] + (11)*sc[6] + (0.9)*sc[9] + (2.8)*sc[10];
qf[9] *= Corr * k_f;
qr[9] *= Corr * k_f * exp(-(2.000000*g_RT[1] - g_RT[5])) * (refC);
// reaction 5:  H + OH + M <=> H2O + M
k_f = 40000000000
           * exp((-2) * logT);
Corr  = mixture + (1.5)*sc[5] + (11)*sc[6] + (0.9)*sc[9] + (2.8)*sc[10];
qf[10] *= Corr * k_f;
qr[10] *= Corr * k_f * exp(-(g_RT[1] + g_RT[3] - g_RT[6])) * (refC);
// reaction 6:  2 O + M <=> O2 + M
k_f = 6170
           * exp((-0.5) * logT);
Corr  = mixture + (1.5)*sc[5] + (11)*sc[6] + (0.9)*sc[9] + (2.8)*sc[10];
qf[11] *= Corr * k_f;
qr[11] *= Corr * k_f * exp(-(-g_RT[2] + 2.000000*g_RT[4])) * (refC);
// reaction 7:  H + O + M <=> OH + M
k_f = 4710000
           * exp((-1) * logT);
Corr  = mixture + (1.5)*sc[5] + (11)*sc[6] + (0.9)*sc[9] + (2.8)*sc[10];
qf[12] *= Corr * k_f;
qr[12] *= Corr * k_f * exp(-(g_RT[1] - g_RT[3] + g_RT[4])) * (refC);
// reaction 8:  H + O2 (+M) <=> HO2 (+M)
k_f = 4650000
           * exp((0.44) * logT);
Corr  = mixture + (1.5)*sc[5] + (15)*sc[6] + (0.2)*sc[9] + (1.4)*sc[10] + (0.5)*sc[20];
redP = Corr / k_f * 57500000 
           * exp(-1.4  * logT);
F = redP / (1.0 + redP);
logPred = log10(redP);
logFcent = log10(
    (0.5)*exp(-T * 1e+30)
    + 0.5 * exp(-T * 1e-30)
    + 0.0);
troe_c = -0.4 - 0.67 * logFcent;
troe_n = 0.75 - 1.27 * logFcent;
troe = (troe_c + logPred) / (troe_n - 0.14*(troe_c + logPred));
F_troe = exp(M_LN10 * logFcent / (1.0 + troe*troe));
Corr = F * F_troe;
qf[0] *= Corr * k_f;
qr[0] *= Corr * k_f * exp(-(g_RT[1] + g_RT[2] - g_RT[7])) * (refC);
// reaction 9:  H + HO2 <=> 2 OH
k_f = 70800000
           * exp(-(148.413691245786) * invT);
qf[32] *= k_f;
