// reaction 12:  HO2 + O <=> O2 + OH
k_f = 20000000
           ;
qf[35] *= k_f;
qr[35] *= k_f * exp(-(-g_RT[2] - g_RT[3] + g_RT[4] + g_RT[7]));
// reaction 13:  HO2 + OH <=> H2O + O2
