// reaction 19:  H + H2O2 <=> H2O + OH
k_f = 10000000
           * exp(-(1804.07703640984) * invT);
qf[41] *= k_f;
qr[41] *= k_f * exp(-(g_RT[1] - g_RT[3] - g_RT[6] + g_RT[8]));
// reaction 20:  H2O2 + OH <=> H2O + HO2
k_f = 1740000
           * exp(-(721.627795263942) * invT);
qf[42] *= k_f;
qr[42] *= k_f * exp(-(g_RT[3] - g_RT[6] - g_RT[7] + g_RT[8]));
// reaction 21:  H2O2 + OH <=> H2O + HO2
k_f = 75900000
           * exp(-(3659.86461739778) * invT);
qf[43] *= k_f;
qr[43] *= k_f * exp(-(g_RT[3] - g_RT[6] - g_RT[7] + g_RT[8]));
// reaction 22:  H2O2 + O <=> HO2 + OH
k_f = 9.63
           * exp((2) * logT - (2008.53899989296) * invT);
qf[44] *= k_f;
qr[44] *= k_f * exp(-(-g_RT[3] + g_RT[4] - g_RT[7] + g_RT[8]));
// reaction 23:  CO + O (+M) <=> CO2 (+M)
k_f = 180000
           * exp(-(1199.70878861172) * invT);
Corr  = mixture + (1.5)*sc[5] + (11)*sc[6] + sc[9] + (3)*sc[10];
redP = Corr / k_f * 1550000000000 
           * exp(-2.79  * logT - (2108.96594988761) *invT);
F = redP / (1.0 + redP);
logPred = log10(redP);
logFcent = log10(
    + exp(-T * 1e-07)
    + exp(-10000000 * invT));
troe_c = -0.4 - 0.67 * logFcent;
troe_n = 0.75 - 1.27 * logFcent;
troe = (troe_c + logPred) / (troe_n - 0.14*(troe_c + logPred));
F_troe = exp(M_LN10 * logFcent / (1.0 + troe*troe));
Corr = F * F_troe;
qf[2] *= Corr * k_f;
qr[2] *= Corr * k_f * exp(-(g_RT[4] + g_RT[9] - g_RT[10])) * (refC);
// reaction 24:  CO + OH <=> CO2 + H
k_f = 4.4
           * exp((1.5) * logT - (-372.843292028033) * invT);
qf[45] *= k_f;
