qf[13] *= Corr * k_f;
qr[13] *= Corr * k_f * exp(-(-g_RT[1] - g_RT[9] + g_RT[11])) * (refCinv);
// reaction 28:  H + HCO <=> CO + H2
k_f = 50000000
           ;
qf[48] *= k_f;
